const DARK={bg:'#111210',card:'#1C1E1B',ink:'#F3F2ED',muted:'#A6A69F',orange:'#FF8058',line:'#30332E',green:'#7EAE89',blue:'#7E9FD2',red:'#E06B59',hero:'#242722',heroMuted:'#B8BBB3',soft:'#292C27',input:'#20221F',check:'#666A62',chevron:'#777B73',placeholder:'#777A73',tabIcon:'#969A92',glass:'rgba(35,38,34,0.74)',glassSelected:'rgba(78,82,75,0.72)',glassBorder:'rgba(255,255,255,0.13)',shadow:'#000000',guide:'#30231E',dot:'#484B45'};
