const STORE='shiguang-data-v2';
const seed={name:'',avatarUri:null,events:[],tasks:[],dataVersion:4,reminders:false,doNotDisturb:false,reminderMinutes:15,themeMode:'system'};
const days=['周一','周二','周三','周四','周五','周六','周日'];
